head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF41621.xml";
// 전역 변수 선언
scwin.vJobMode = "";
scwin.vIsurCd = "";
scwin.vBzProcsNo = "";
scwin.vSeq = "";
scwin.vDeleteAll = "";
scwin.vCMIT_CONTN_NM = "";
scwin.vCMIT_CONTN = "";
scwin.vUpdates = "";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.initCtrl();
    scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
    buttonSet.setSaveInfo(btn_save, fn_save);
    buttonSet.setUpdateInfo(btn_update, fn_update);
    buttonSet.setDeleteInfo(btn_delete, fn_delete);
    if (scwin.vJobMode === "M") {
        btn_ISUR_CD.hide();
        btn_save.setDisabled(true);
        btn_save.setBackgroundImage("../img/btn_save_d.gif");
        scwin.vBzProcsNo = $c.frame.path("../").scwin.vBzProcsNo;
        scwin.vIsurCd = $c.frame.path("../").scwin.vIsurCd;
        vIsurNm = $c.frame.path("../").vIsurNm;
        txb_ISUR_CD.setValue(scwin.vIsurCd);
        txb_COM_NM.setValue(vIsurNm);
        buttonSet.setUpdateStatus();
        scwin.listPreInvstg();
        scwin.listSync();
    }
    if (scwin.vJobMode === "I") {
        scwin.initDataset();
        buttonSet.setInsertStatus();
    }
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};

scwin.trs_Save_OnSuccess = function() {
    scwin.parentRefresh();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
};

scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};

scwin.trs_Update_OnSuccess = function() {
    scwin.parentRefresh();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
};

scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};

scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    scwin.parentRefresh();
    await $c.win.closePopup();
};

scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};

scwin.trs_count_OnSuccess = function() {
    $c.win.alert('trs_count.OnSuccess()');
};

scwin.trs_count_OnFail = function() {
    $c.win.alert(trs_count.ErrorMsg);
};

scwin.dts_fileList_OnLoadError = function() {
    $c.win.alert(dts_List);
};

scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    if (rowcount === 0) {
        buttonSet.setInsertStatus();
    } else {
        buttonSet.setUpdateStatus();
    }
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
};

scwin.dts_ContentsInfo_OnLoadError = function() {
    $c.win.alert(dts_ContentsInfo);
};

scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {

};

scwin.btn_Search_onclick = function() {
    scwin.listSync();
};

scwin.btn_ISUR_CD_onclick = function() {
    fn_GetPar = fn_GetPar;
    fn_SetPar = fn_SetPar;
    scwin.popFindListinvstgApfmCorp();
    scwin.listPreInvstg();
    scwin.listSync();
};

scwin.grd_fileList_onheadcheckclick = function(col, colid, bCheck) {
    scwin.setCheckBox(colid, bCheck);
};

scwin.btn_approve_onclick = function() {
    scwin.approve();
};

scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

scwin.inf_find_OnClick = function() {
    const filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() === "") {
        file_name.setValue(filenm);
    }
};

scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "REG_ID", js_emp_no);
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO", dts_ContentsInfo.getCellData(1, "BZ_PROCS_NO"));
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_ATTACH_FILE_TP_CD", "10");
};

scwin.btn_linedelete_onclick = function() {
    scwin.linedelete();
};

scwin.grd_fileList_OnPopup = function(row, colid, data) {
    if (colid === "filename") {
        scwin.cmitdeadlineFile();
    }
};

scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (colid === "CMIT_CONTN_NM" || colid === "CMIT_CONTN") {
        scwin.openCmitcontn(row);
    } else if (colid === "filename" && dts_fileList.getCellData(row, "filename") !== "") {
        scwin.cmitFiledown(row, "10");
    } else if (colid === "CMIT_PERFM_STAT_NM" || colid === "PERFM_OPIN_CONTN") {
        scwin.openPerfm(row);
    } else if (colid === "CEVDN_filename" && dts_fileList.getCellData(row, "CEVDN_filename") !== "") {
        scwin.cmitFiledown(row, "20");
    }
};

scwin.grd_fileList_onlbuttondblclk = function(row, colid, xpos, ypos) {
    if (colid === 'CMIT_DEADLINE_DD' && row > 0) {
        scwin.gridDateSet2(grd_fileList, row, colid, "yyyymmdd", xpos, ypos);
    }
    if (colid === 'CMIT_CONTN' && row > 0) {

    }
    return true;
};

// 일반 함수
scwin.initCtrl = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
};

scwin.initDataset = function() {
    const sbmOptions = {
        id : "sbm_dts_ContentsInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ContentsInfo=body.content",
        submitDoneHandler : scwin.sbm_dts_ContentsInfo_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);

    dts_ContentsInfo.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_fileList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileList=body.content",
        submitDoneHandler : scwin.sbm_dts_fileList_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);

};

scwin.listPreInvstg = function() {
    const sbmOptions = {
        id : "sbm_dts_ContentsInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ContentsInfo=body.content",
        submitDoneHandler : scwin.sbm_dts_ContentsInfo_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);

};

scwin.listSync = function() {
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_fileList=body.content",
        submitDoneHandler : scwin.sbm_dts_fileList_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);

};

scwin.getPar = function(arrPar) {
    arrPar[0] = txb_ISUR_CD;
    arrPar[1] = txb_COM_NM;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

scwin.setPar = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    txb_ISUR_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : "")); /*ORG SRC: dts_ContentsInfo.NameValue(1, "BZ_PROCS_NO") = (arrPar.length >= 3 ? arrPar[2] : "");*/ X = (arrPar.length >= 3 ? arrPar[2] : "");
};

scwin.cmitdeadlineFile = function() {
    inf_find.open();
    if (inf_find.getValue() !== "") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "filename", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
        return true;
    } else return false;
};

scwin.save = function() {
    let rtn = confirm('등록 하시겠습니까?');
    if (rtn === 1) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/CmitDeadLine.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Save=body.content",
            submitDoneHandler : scwin.sbm_trs_Save_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.update = function() {
    let rtn = confirm('수정 하시겠습니까?');
    if (rtn === 1) {
        dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/CmitDeadLine.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Update=body.content",
            submitDoneHandler : scwin.sbm_trs_Update_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);
    }
};

scwin.delete = function() {
    let msg = '전체 삭제 하시겠습니까?';
    let rtn = confirm(msg);
    if (rtn === 1) {

        //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ContentsDel.insertRow();
        // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     BZ_PROCS_NO : dts_ContentsInfo.getCellData(dts_ContentsInfo.getRowPosition(), "BZ_PROCS_NO"),
        //     CMIT_CONTN_SEQ : "",
        //     REG_ID : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/CmitDeadLine.do",
            ref : "dts_ContentsDel",
            target : "trs_Delete=body.content",
            submitDoneHandler : scwin.sbm_trs_Delete_submitdone,
            isProcessMsg : false
        };

        $c.sbm.executeDynamic(sbmOptions);
    }
    return rtn;
};

scwin.approve = function() {
    let cnt = 0;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") cnt++;
    }
    if (cnt === 0) {
        $c.win.alert("체크박스 선택한 항목이 없습니다.");
        return;
    } else {
        let rtn = confirm(cnt + "건 항목 승인 하시겠습니까?");
        if (rtn === 1) scwin.approvelItems();
    }
};

scwin.approvelItem = function() {
    let msg = dts_fileList.getCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_SEQ") + "번째  " + dts_fileList.getCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_NM") + '항목 승인 하시겠습니까?';
    let rtn = confirm(msg);
    if (rtn === 0) return;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") {
            dts_fileList.setCellData(i, "CMIT_PERFM_STAT_CD", "40");
        }
    }
    dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
    const sbmOptions = {
        id : "sbm_trs_Update",
        action : "/CmitDeadLine.do",
        ref : "dts_fileList",
        target : "trs_Update=body.content",
        submitDoneHandler : scwin.sbm_trs_Update_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

scwin.approvelItems = function() {
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") {
            dts_fileList.setCellData(i, "CMIT_PERFM_STAT_CD", "40");
        }
    }
    dts_ContentsInfo.setCellData(1, "REG_ID", js_emp_no);
    const sbmOptions = {
        id : "sbm_trs_Update",
        action : "/CmitDeadLine.do",
        ref : "dts_ContentsInfo,dts_fileList",
        target : "trs_Update=body.content",
        submitDoneHandler : scwin.sbm_trs_Update_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

scwin.linedelete = function() {
    let cnt = 0;
    let msg = '';
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") {
            cnt++;
            msg += i + ", ";
        }
    }
    if (cnt === 0)
        //deleteItem();
        $c.win.alert("삭제할 항목이 없습니다.");

    else {
        //var rtn = confirm( msg + "항목 삭제 하시겠습니까?");
        //if (rtn == 1) {
        scwin.deleteItems();
        //}

    }
};

scwin.deleteItems = function() {
    grd_fileList.Redraw = false;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") {
            dts_fileList.removeRows(i);
            i = i--;
        }
    }
    grd_fileList.Redraw = true;
};

scwin.deleteItem = function() {
    let msg = dts_fileList.getCellData(dts_fileList.getRowPosition(), "SEQ") + "번째  " + dts_fileList.getCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_NM") + '항목 삭제 하시겠습니까?';
    let rtn = confirm(msg);
    if (rtn === 0) return;
    if (dts_fileList.getCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_SEQ") === "0") {
        dts_fileList.removeRows(dts_fileList.getRowPosition());
        return;
    }
    //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_ContentsDel.insertRow();
    // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     BZ_PROCS_NO : dts_fileList.getCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO"),
    //     CMIT_CONTN_SEQ : dts_fileList.getCellData(dts_fileList.getRowPosition(), "CMIT_CONTN_SEQ"),
    //     REG_ID : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/CmitDeadLine.do",
        ref : "dts_ContentsDel",
        target : "trs_Delete=body.content",
        submitDoneHandler : scwin.sbm_trs_Delete_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

scwin.cmitFiledown = function(row, fileTpCd) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + dts_fileList.getCellData(row, "BZ_PROCS_NO") + "&CMIT_CONTN_SEQ=" + dts_fileList.getCellData(row, "CMIT_CONTN_SEQ") + "&CMIT_CONTN_ATTACH_FILE_TP_CD=" + fileTpCd + // 10 확약서 20 증빙서
        "&gubun=50"; //FileDownLoadAction.java

};

scwin.openCmitcontn = async function(row) {
    let wth = 650;
    let hgt = 400;
    let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    scwin.vCMIT_CONTN_NM = dts_fileList.getCellData(row, "CMIT_CONTN_NM");
    scwin.vCMIT_CONTN = dts_fileList.getCellData(row, "CMIT_CONTN");
    await $c.frame.CreateDialogFrame("CMIT_CONTN", "/lstmgt/ULDSTF41624.gfm", "확약사항입력", pt.x, pt.y, wth, hgt, "window");
    if (scwin.vUpdates === 'Y') {
        dts_fileList.setCellData(row, "CMIT_CONTN_NM", scwin.vCMIT_CONTN_NM);
        dts_fileList.setCellData(row, "CMIT_CONTN", scwin.vCMIT_CONTN);
        scwin.vUpdates = '';
    }
};

scwin.openPerfm = async function(row) {
    let wth = 700;
    let hgt = 450;
    let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    scwin.vBzProcsNo = dts_fileList.getCellData(row, "BZ_PROCS_NO");
    scwin.vSeq = dts_fileList.getCellData(row, "CMIT_CONTN_SEQ");
    scwin.vIsurCd = dts_fileList.getCellData(row, "ISUR_CD");
    if (dts_fileList.getCellData(row, "CMIT_PERFM_STAT_NM") !== "") await $c.frame.CreateDialogFrame("CMIT_CONTN", "/lstmgt/ULDSTF41622.gfm", "수정요청사항", pt.x, pt.y, wth, hgt, "window");
};

scwin.setCheckBox = function(colid, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grd_fileList.Redraw = false;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        dts_fileList.setCellData(i, colid, vcd);
    }
    grd_fileList.Redraw = true;
};

scwin.popFindListinvstgApfmCorp = async function() {
    let wth = 550;
    let hgt = 580;
    let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("DLG_PRECOM_SEL", "../lstmgt/ULDSTF41623.gfm", "회사선택", 470, 30, wth, hgt, "window");
};

scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};

scwin.gridDateSet2 = function(grdObj, row, colid, format, xpos, ypos) {
    ctlToPlaceValue = document.all(grdObj.DataId);
    gridType = "Y";
    pColid = colid;
    pRow = row;
    const leftpos = 0;
    const toppos = 0;
    const aData = new Array();
    if (bPageLoaded) {
        dateFormat = format;
        formatChar = "-";
        aFormat = dateFormat.replace(/(^\s*)|(\s*$)/g, "");
        if (aFormat.length === 10) {
            aFormat = dateFormat.split(formatChar);
        } else {
            formatChar = "";
        }
        if (aFormat.length < 3) {

        }
        tokensChanged = '0';
        if (formatChar !== "") {
            //insertdata = eval(ctl2).Text;
            insertdata = grdObj.getCellData(row, colid);
            aData[0] = insertdata.substr(0, 4);
            aData[1] = insertdata.substr(4, 2);
            aData[2] = insertdata.substr(6, 2);
            for (let i = 0; i < 3; i++) {
                if ((aFormat[i] === "d") || (aFormat[i] === "dd")) {
                    dateSelected = parseInt(aData[i], 10);
                    tokensChanged++;
                } else if ((aFormat[i] === "m") || (aFormat[i] === "mm")) {
                    monthSelected = parseInt(aData[i], 10) - 1;
                    tokensChanged++;
                } else if (aFormat[i] === "yyyy") {
                    yearSelected = parseInt(aData[i], 10);
                    tokensChanged++;
                } else if (aFormat[i] === "mmm") {
                    for (let j = 0; j < 12; j++) {
                        if (aData[i] === monthName[j]) {
                            monthSelected = j;
                            tokensChanged++;
                        }
                    }
                } else if (aFormat[i] === "mmmm") {
                    for (let j = 0; j < 12; j++) {
                        if (aData[i] === monthName2[j]) {
                            monthSelected = j;
                            tokensChanged++;
                        }
                    }
                }
            }
        }
        if ((tokensChanged !== 3) || isNaN(dateSelected) || isNaN(monthSelected) || isNaN(yearSelected)) {
            dateSelected = dateNow;
            monthSelected = monthNow;
            yearSelected = yearNow;
        }
        odateSelected = dateSelected;
        omonthSelected = monthSelected;
        oyearSelected = yearSelected;
        cleft = xpos;
        ctop = ypos + 110;
        constructCalendar(1, monthSelected, yearSelected);
        bShow = true;
    }
};
